"use strict";
import { useAccount } from "hooks/useAccount";
import { useCallback, useEffect, useState } from "react";
import { useTransactionAdder } from "state/transactions/hooks";
import { TransactionType } from "state/transactions/types";
import styled from "styled-components";
import { Flex, SpinningLoader, Text, useSporeColors } from "ui/src";
import { useReadContract, useWaitForTransactionReceipt, useWriteContract } from "wagmi";
import { useIncentivizeContext } from "../ContextProvider";
const ERC20_ABI = [
  {
    inputs: [
      { internalType: "address", name: "spender", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "approve",
    outputs: [{ internalType: "bool", name: "", type: "bool" }],
    stateMutability: "nonpayable",
    type: "function"
  },
  {
    inputs: [
      { internalType: "address", name: "owner", type: "address" },
      { internalType: "address", name: "spender", type: "address" }
    ],
    name: "allowance",
    outputs: [{ internalType: "uint256", name: "", type: "uint256" }],
    stateMutability: "view",
    type: "function"
  }
];
const BRIBE_ABI = [
  {
    inputs: [
      { internalType: "address", name: "token", type: "address" },
      { internalType: "uint256", name: "amount", type: "uint256" }
    ],
    name: "notifyRewardAmount",
    outputs: [],
    stateMutability: "nonpayable",
    type: "function"
  }
];
export default function ChangePoolAndIncentivizeButton() {
  const { setIncentivizeStep, selectedPool, incentiveAmount, incentiveToken, termsAccepted } = useIncentivizeContext();
  const colors = useSporeColors();
  const account = useAccount();
  const addTransaction = useTransactionAdder();
  const [flowStep, setFlowStep] = useState(
    "input"
  );
  const [lastTransactionStep, setLastTransactionStep] = useState(null);
  const bribeAddress = selectedPool?.gauge?.bribeContract;
  const tokenAddress = incentiveToken?.address;
  const { writeContract, data: writeData, isPending: isWritePending, error: writeError } = useWriteContract();
  const {
    isLoading: isConfirming,
    isSuccess,
    error: receiptError
  } = useWaitForTransactionReceipt({
    hash: writeData
  });
  const { data: allowance, refetch: refetchAllowance } = useReadContract({
    address: tokenAddress,
    abi: ERC20_ABI,
    functionName: "allowance",
    args: account.address && bribeAddress ? [account.address, bribeAddress] : void 0,
    query: { enabled: !!tokenAddress && !!bribeAddress && !!account.address }
  });
  const needsApproval = useCallback(() => {
    if (!allowance || !incentiveAmount) return true;
    const amountBigInt = BigInt(incentiveAmount.quotient.toString());
    return allowance < amountBigInt;
  }, [allowance, incentiveAmount]);
  const handleApprove = useCallback(async () => {
    if (!tokenAddress || !bribeAddress || !incentiveAmount) return;
    try {
      setFlowStep("approve");
      setLastTransactionStep("approve");
      const maxAmount = BigInt("0xffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff");
      await writeContract({
        address: tokenAddress,
        abi: ERC20_ABI,
        functionName: "approve",
        args: [bribeAddress, maxAmount]
      });
    } catch (error) {
      console.error("Approval failed:", error);
      setFlowStep("error");
      setLastTransactionStep(null);
    }
  }, [writeContract, tokenAddress, bribeAddress, incentiveAmount]);
  const handleIncentivize = useCallback(async () => {
    if (!account.address || !tokenAddress || !bribeAddress || !incentiveAmount) return;
    try {
      setFlowStep("incentivize");
      setLastTransactionStep("incentivize");
      const amount = BigInt(incentiveAmount.quotient.toString());
      console.log("Submitting incentive to bribe contract:", bribeAddress);
      console.log("Token:", tokenAddress, "Amount:", amount.toString());
      await writeContract({
        address: bribeAddress,
        abi: BRIBE_ABI,
        functionName: "notifyRewardAmount",
        args: [tokenAddress, amount]
      });
    } catch (error) {
      console.error("Incentivization failed:", error);
      setFlowStep("error");
      setLastTransactionStep(null);
    }
  }, [writeContract, account.address, tokenAddress, bribeAddress, incentiveAmount]);
  const executeFlow = useCallback(async () => {
    if (!account.address || !selectedPool || !incentiveAmount || !incentiveToken) return;
    if (needsApproval()) {
      await handleApprove();
    } else {
      await handleIncentivize();
    }
  }, [account.address, selectedPool, incentiveAmount, incentiveToken, needsApproval, handleApprove, handleIncentivize]);
  useEffect(() => {
    if (isConfirming) {
      setFlowStep("confirming");
    } else if (isSuccess && lastTransactionStep) {
      if (lastTransactionStep === "approve") {
        setLastTransactionStep(null);
        setTimeout(() => {
          refetchAllowance().then(() => {
            handleIncentivize();
          });
        }, 1e3);
      } else if (lastTransactionStep === "incentivize") {
        setLastTransactionStep(null);
        setFlowStep("success");
        if (writeData && tokenAddress && bribeAddress && incentiveAmount) {
          addTransaction(
            { hash: writeData },
            {
              type: TransactionType.APPROVAL,
              // TODO: Add INCENTIVE type if needed
              tokenAddress,
              spender: bribeAddress,
              amount: incentiveAmount.quotient.toString()
            }
          );
        }
        setTimeout(() => {
          setIncentivizeStep("step-1");
          setFlowStep("input");
        }, 2e3);
      }
    } else if (writeError || receiptError) {
      const error = writeError || receiptError;
      const errorMessage = error?.message || "Transaction failed";
      const isUserRejection = errorMessage.toLowerCase().includes("user rejected") || errorMessage.toLowerCase().includes("user denied");
      if (isUserRejection) {
        setFlowStep("input");
      } else {
        setFlowStep("error");
      }
      setLastTransactionStep(null);
    }
  }, [
    isConfirming,
    isSuccess,
    writeError,
    receiptError,
    lastTransactionStep,
    writeData,
    tokenAddress,
    bribeAddress,
    incentiveAmount,
    addTransaction,
    setIncentivizeStep,
    refetchAllowance,
    handleIncentivize
  ]);
  const Button = styled.button`
    all: unset;
    padding: 16px 10px;
    background-color: ${(props) => props.$disabled ? colors.surface2.val : props.$lock ? colors.surface2Hovered.val : colors.accent1.val};
    color: ${(props) => props.$disabled ? colors.neutral3.val : props.$lock ? colors.neutral1.val : colors.surface1.val};
    border-radius: 12px;
    border: 1px solid ${colors.surface3.val};
    cursor: ${(props) => props.$disabled ? "not-allowed" : "pointer"};
    display: flex;
    justify-content: center;
    align-items: center;
    flex-grow: 1;
    transition: all 0.2s ease;
    &:hover {
      opacity: ${(props) => props.$disabled ? 1 : 0.7};
    }
  `;
  const isProcessing = isWritePending || isConfirming;
  const isDisabled = isProcessing || !account.address || !selectedPool || !incentiveAmount || !incentiveToken || !termsAccepted;
  const showApproval = needsApproval();
  const getButtonText = () => {
    if (!termsAccepted) return "Accept Terms First";
    if (flowStep === "approve") return "Approving...";
    if (flowStep === "incentivize") return "Submitting...";
    if (flowStep === "confirming") return "Confirming...";
    if (flowStep === "success") return "Success!";
    if (flowStep === "error") return "Try Again";
    if (showApproval) return `Approve ${incentiveToken?.symbol || "Token"}`;
    return "Incentivize";
  };
  return <Flex mt={"$spacing24"} row gap={"$gap12"} alignItems="center">
      <Button role="button" $lock onClick={() => setIncentivizeStep("step-1")}>
        <Text variant="buttonLabel3" color={"inherit"}>
          Change Pool
        </Text>
      </Button>
      <Button role="button" onClick={executeFlow} $disabled={isDisabled}>
        <Flex row gap={"$gap8"} alignItems="center">
          {(flowStep === "approve" || flowStep === "incentivize" || flowStep === "confirming") && <SpinningLoader size={20} />}
          <Text variant="buttonLabel3" color={"inherit"}>
            {getButtonText()}
          </Text>
        </Flex>
      </Button>
    </Flex>;
}
