"use strict";
import { Flex, Text, useSporeColors } from "ui/src";
import { DoubleCurrencyLogo } from "components/Logo/DoubleLogo";
import { MouseoverTooltip, TooltipSize } from "components/Tooltip";
import { Token } from "@uniswap/sdk-core";
import { ABSTRACT_TESTNET_CHAIN_ID } from "uniswap/src/constants/contracts";
import { useMemo } from "react";
import { useFormatter } from "utils/formatNumbers";
import { TrendingUp, TrendingDown, DollarSign, Award } from "react-feather";
export function UserGaugeDepositCard({
  deposit,
  showRewards = true,
  compact = false,
  onDepositClick
}) {
  const colors = useSporeColors();
  const formatter = useFormatter();
  const currencies = useMemo(() => {
    if (!deposit.token0Address || !deposit.token1Address) return [void 0, void 0];
    try {
      const token0 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        deposit.token0Address,
        18,
        // Default to 18 decimals
        deposit.token0Symbol || "Unknown",
        deposit.token0Symbol || "Unknown Token"
      );
      const token1 = new Token(
        ABSTRACT_TESTNET_CHAIN_ID,
        deposit.token1Address,
        18,
        deposit.token1Symbol || "Unknown",
        deposit.token1Symbol || "Unknown Token"
      );
      return [token0, token1];
    } catch (error) {
      console.warn("Failed to create tokens for deposit display:", error);
      return [void 0, void 0];
    }
  }, [deposit.token0Address, deposit.token1Address, deposit.token0Symbol, deposit.token1Symbol]);
  const pairName = deposit.token0Symbol && deposit.token1Symbol ? `${deposit.token0Symbol}/${deposit.token1Symbol}` : "Unknown Pair";
  const poolTypeLabel = deposit.poolType === "V2" ? "Basic Stable" : deposit.poolType === "V3" ? "Concentrated Volatile" : deposit.poolType;
  const hasStakedAmount = parseFloat(deposit.stakedAmount) > 0;
  const hasUnstakedAmount = parseFloat(deposit.unstakedAmount) > 0;
  const hasPendingRewards = parseFloat(deposit.pendingRewards) > 0;
  const handleCardClick = () => {
    if (onDepositClick) {
      onDepositClick(deposit);
    }
  };
  if (compact) {
    return <Flex
      row
      alignItems="center"
      justifyContent="space-between"
      py="$spacing8"
      px="$spacing12"
      borderRadius="$rounded8"
      backgroundColor="$surface2"
      cursor={onDepositClick ? "pointer" : "default"}
      hoverStyle={onDepositClick ? { backgroundColor: "$surface2Hovered" } : void 0}
      onPress={handleCardClick}
    >
        <Flex row alignItems="center" gap="$gap8">
          <DoubleCurrencyLogo currencies={currencies} size={24} />
          <Text variant="body3" fontWeight="$medium">
            {pairName}
          </Text>
        </Flex>
        
        <Flex row alignItems="center" gap="$gap16">
          {hasStakedAmount && <Flex alignItems="flex-end">
              <Text variant="body4" color="$accent1">
                {deposit.stakedAmount}
              </Text>
              <Text variant="caption" color="$neutral3">
                Staked
              </Text>
            </Flex>}
          
          {hasUnstakedAmount && <Flex alignItems="flex-end">
              <Text variant="body4" color="$neutral2">
                {deposit.unstakedAmount}
              </Text>
              <Text variant="caption" color="$neutral3">
                Available
              </Text>
            </Flex>}
          
          {showRewards && hasPendingRewards && <Flex alignItems="flex-end">
              <Text variant="body4" color="$accent2">
                {deposit.pendingRewards}
              </Text>
              <Text variant="caption" color="$neutral3">
                Rewards
              </Text>
            </Flex>}
        </Flex>
      </Flex>;
  }
  return <Flex
    p="$spacing16"
    borderRadius="$rounded12"
    borderWidth={1}
    borderColor="$surface3"
    hoverStyle={{ borderColor: "$surface3Hovered" }}
    style={{
      background: `linear-gradient(135deg, ${colors.surface1.variable} 0%, ${colors.surface2.variable} 100%)`
    }}
    cursor={onDepositClick ? "pointer" : "default"}
    onPress={handleCardClick}
    gap="$gap16"
  >
      {
    /* Header with pair info */
  }
      <Flex row alignItems="center" justifyContent="space-between">
        <Flex row alignItems="center" gap="$gap12">
          <DoubleCurrencyLogo currencies={currencies} size={32} />
          <Flex>
            <Text variant="subheading2" fontWeight="$bold">
              {pairName}
            </Text>
            <Text variant="body4" color="$neutral2">
              {poolTypeLabel} Pool
            </Text>
          </Flex>
        </Flex>
        
        {deposit.apr !== "N/A" && <MouseoverTooltip text="Current APR from gauge rewards" size={TooltipSize.Small}>
            <Flex
    row
    alignItems="center"
    gap="$gap4"
    py="$spacing4"
    px="$spacing8"
    borderRadius="$rounded8"
    backgroundColor="$accent2"
  >
              <TrendingUp size={12} color={colors.accent1.val} />
              <Text variant="body4" color="$accent1" fontWeight="$medium">
                {deposit.apr}
              </Text>
            </Flex>
          </MouseoverTooltip>}
      </Flex>

      {
    /* Deposit amounts */
  }
      <Flex
    row
    justifyContent="space-between"
    alignItems="center"
    p="$spacing12"
    borderRadius="$rounded8"
    backgroundColor="$surface3"
    gap="$gap16"
  >
        {hasStakedAmount && <Flex alignItems="center" gap="$gap8">
            <Flex
    width={40}
    height={40}
    borderRadius="$rounded8"
    alignItems="center"
    justifyContent="center"
    backgroundColor="$accent1"
  >
              <TrendingUp size={16} color="white" />
            </Flex>
            <Flex>
              <Text variant="body3" fontWeight="$bold" color="$accent1">
                {deposit.stakedAmount}
              </Text>
              <Text variant="caption" color="$neutral3">
                Staked in Gauge
              </Text>
            </Flex>
          </Flex>}

        {hasUnstakedAmount && <Flex alignItems="center" gap="$gap8">
            <Flex
    width={40}
    height={40}
    borderRadius="$rounded8"
    alignItems="center"
    justifyContent="center"
    backgroundColor="$neutral2"
  >
              <DollarSign size={16} color="white" />
            </Flex>
            <Flex>
              <Text variant="body3" fontWeight="$bold">
                {deposit.unstakedAmount}
              </Text>
              <Text variant="caption" color="$neutral3">
                Available to Stake
              </Text>
            </Flex>
          </Flex>}

        {!hasStakedAmount && !hasUnstakedAmount && <Flex alignItems="center" justifyContent="center" flex={1}>
            <Text variant="body3" color="$neutral3">
              No deposits found
            </Text>
          </Flex>}
      </Flex>

      {
    /* Rewards section */
  }
      {showRewards && <Flex gap="$gap12">
          <Flex row justifyContent="space-between" alignItems="center">
            <Text variant="body3" color="$neutral2" fontWeight="$medium">
              Rewards
            </Text>
            {hasPendingRewards && <MouseoverTooltip text="Click to claim pending rewards" size={TooltipSize.Small}>
                <Award size={14} color={colors.accent2.val} />
              </MouseoverTooltip>}
          </Flex>
          
          <Flex row justifyContent="space-between" alignItems="center">
            <Flex>
              <Text variant="body4" color="$neutral3">
                Pending
              </Text>
              <Text variant="body3" fontWeight="$bold" color={hasPendingRewards ? "$accent2" : "$neutral3"}>
                {deposit.pendingRewards} ABX
              </Text>
            </Flex>
            
            <Flex alignItems="flex-end">
              <Text variant="body4" color="$neutral3">
                Total Earned
              </Text>
              <Text variant="body3" fontWeight="$bold">
                {deposit.totalEarnedRewards} ABX
              </Text>
            </Flex>
          </Flex>
        </Flex>}

      {
    /* Position count */
  }
      {deposit.positions.length > 0 && <Flex row alignItems="center" gap="$gap8" pt="$spacing8" borderTopWidth={1} borderTopColor="$surface3">
          <Text variant="caption" color="$neutral3">
            {deposit.positions.length} position{deposit.positions.length > 1 ? "s" : ""}
            {deposit.positions.some((p) => p.stakedInGauge) && " \u2022 Some staked in gauge"}
          </Text>
        </Flex>}
    </Flex>;
}
export function UserGaugeDepositsList({
  deposits,
  isLoading = false,
  showRewards = true,
  compact = false,
  emptyMessage = "No gauge deposits found",
  onDepositClick
}) {
  const colors = useSporeColors();
  if (isLoading) {
    return <Flex gap="$gap12" p="$spacing16">
        <Text variant="body3" color="$neutral3">
          Loading your gauge deposits...
        </Text>
        {[1, 2, 3].map((i) => <Flex
      key={i}
      height={compact ? 60 : 120}
      borderRadius="$rounded12"
      backgroundColor="$surface2"
      opacity={0.5}
    />)}
      </Flex>;
  }
  if (!deposits.length) {
    return <Flex
      alignItems="center"
      justifyContent="center"
      p="$spacing24"
      gap="$gap16"
      borderRadius="$rounded12"
      borderWidth={1}
      borderColor="$surface3"
      borderStyle="dashed"
    >
        <TrendingDown size={32} color={colors.neutral3.val} />
        <Flex alignItems="center" gap="$gap8">
          <Text variant="body2" color="$neutral3">
            {emptyMessage}
          </Text>
          <Text variant="body4" color="$neutral3" textAlign="center">
            Start by depositing liquidity into pools and staking in gauges to earn rewards
          </Text>
        </Flex>
      </Flex>;
  }
  return <Flex gap="$gap12">
      {deposits.map((deposit) => <UserGaugeDepositCard
    key={`${deposit.gaugeAddress}-${deposit.poolAddress}`}
    deposit={deposit}
    showRewards={showRewards}
    compact={compact}
    onDepositClick={onDepositClick}
  />)}
    </Flex>;
}
export function UserGaugeDepositsSummary({ summary, isLoading = false }) {
  const colors = useSporeColors();
  const formatter = useFormatter();
  if (isLoading) {
    return <Flex
      row
      gap="$gap16"
      p="$spacing16"
      borderRadius="$rounded12"
      backgroundColor="$surface2"
      opacity={0.5}
    >
        <Flex flex={1} gap="$gap4">
          <Flex height={16} width={60} backgroundColor="$surface3" borderRadius="$rounded4" />
          <Flex height={20} width={80} backgroundColor="$surface3" borderRadius="$rounded4" />
        </Flex>
      </Flex>;
  }
  const summaryCards = [
    {
      label: "Active Deposits",
      value: summary.totalDeposits.toString(),
      color: "$neutral1",
      icon: DollarSign
    },
    {
      label: "Total Staked",
      value: summary.totalStakedValue,
      color: "$accent1",
      icon: TrendingUp
    },
    {
      label: "Available to Stake",
      value: summary.totalUnstakedValue,
      color: "$neutral2",
      icon: DollarSign
    },
    {
      label: "Pending Rewards",
      value: `${summary.totalPendingRewards} ABX`,
      color: "$accent2",
      icon: Award
    },
    {
      label: "Average APR",
      value: summary.averageAPR,
      color: summary.averageAPR !== "N/A" ? "$accent1" : "$neutral3",
      icon: TrendingUp
    }
  ];
  return <Flex
    row
    gap="$gap12"
    p="$spacing16"
    borderRadius="$rounded12"
    style={{
      background: `linear-gradient(135deg, ${colors.surface1.variable} 0%, ${colors.surface2.variable} 100%)`
    }}
    borderWidth={1}
    borderColor="$surface3"
  >
      {summaryCards.map((card, index) => <Flex key={index} flex={1} alignItems="center" gap="$gap8">
          <Flex
    width={32}
    height={32}
    borderRadius="$rounded8"
    alignItems="center"
    justifyContent="center"
    backgroundColor={card.color}
    opacity={0.2}
  >
            <card.icon size={16} color={colors[card.color.slice(1)]?.val} />
          </Flex>
          <Flex flex={1}>
            <Text variant="caption" color="$neutral3">
              {card.label}
            </Text>
            <Text variant="body3" fontWeight="$bold" color={card.color}>
              {card.value}
            </Text>
          </Flex>
        </Flex>)}
    </Flex>;
}
